            (F : bvmap 5 word) (fc : bv 32) (m0 m : mem).
  Variables (lo addr size v : Z) (j8 : list byte) (sbs : list byte).
  Hypothesis MI : mem_inv bsegs m.
  Hypothesis MU : munch [(bv_unsigned sp - 64, bv_unsigned sp); (sh addr, sh addr + size / 8)]%Z m0 m.
  Hypothesis WM : wmono bsegs m0 m.
  Hypothesis ST : stk bsegs m lo (bv_unsigned sp + -64).
  Hypothesis LO : aceil <= lo.  Hypothesis HI : lo + 64 <= bv_unsigned sp.
  Hypothesis FR : rw_cells bsegs m (bv_unsigned sp + -64) [CB 8 j8; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].
  (* [comment removed for export] *)
  Hypothesis AR : ((AHI_LO <= addr /\ AHI_LO + 8 <= addr + size) \/ (0 <= addr /\ 8 <= addr + size /\ addr + size <= ALOWSH_LO))
                  /\ addr + size <= aceil /\ addr mod 8 = 0 /\ size mod 8 = 0 /\ 0 <= size.
  Hypothesis VR : 0 <= v < 256.
  Hypothesis SH : u8arr bsegs m (sh addr) sbs.  Hypothesis SHL : Z.of_nat (length sbs) = size / 8.
  Hypothesis GOT : rw_cells bsegs m AGOT_LO (map (fun v => C8 (wz v)) AGOT_VALS).
  Hypothesis CSHB : rw_cells bsegs m ASHBASE_CELL [C8 (wz ASHADOW_BASE)].
  Hypothesis CHME : rw_cells bsegs m AHIGHMEMEND [C8 (wz (2^47 - 1)); C8 (wz 0); C8 (wz 0)].
  Hypothesis CTHR : rw_cells bsegs m (ACFLAGS + 120) [C8 (wz 0xffffffffffffffff)].
  Hypothesis CRMS : rw_cells bsegs m AREALMEMSET [C8 (wz AMEMSET)].

  Ltac ps_prep :=
    unfold wz, AGOT_LO, AGOT_VALS, ASHBASE_CELL, ASHADOW_BASE, AHIGHMEMEND, ACFLAGS, AREALMEMSET, AMEMSET, AHI_LO, ALOWSH_LO in *; cbn [map] in GOT;
    change (2^47 - 1) with 140737488355327 in CHME; change (1831656 + 120) with 1831776 in CTHR;
    pose proof (bv_unsigned_in_range _ sp) as SPR; change (bv_modulus 64) with (2^64) in SPR; acb.
