  Lemma poison_walk2 : forall (x13 : word),
    evt bsegs (poison_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 lo addr size v)
      (MS (mkR ra (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 s0 s1 (wz addr) (wz size) (wz v) x13 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
          F (Z_to_bv 64 0x075898) fc None m (seg_rom bsegs)).
  Proof.
    intros x13. destruct (proj1 AR) as [[H _]|(_ & _ & H)]; [apply poison_walk2H; exact H| apply poison_walk2L; exact H].
  Qed.
End Part2.

Section Spec.
  Variables (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : mem).
  Variables (lo addr size v : Z) (sbs : list byte).
  Hypothesis MI : mem_inv bsegs m.
  Hypothesis ST : stk bsegs m lo (bv_unsigned sp).
  Hypothesis LO : aceil <= lo.  Hypothesis HI : lo + 64 <= bv_unsigned sp.
  Hypothesis Ha0 : a0 = wz addr. Hypothesis Ha1 : a1 = wz size. Hypothesis Ha2 : a2 = wz v.
  (* [comment removed for export] *)
  Hypothesis AR : ((AHI_LO <= addr /\ AHI_LO + 8 <= addr + size) \/ (0 <= addr /\ 8 <= addr + size /\ addr + size <= ALOWSH_LO))
                  /\ addr + size <= aceil /\ addr mod 8 = 0 /\ size mod 8 = 0 /\ 0 <= size.
  Hypothesis VR : 0 <= v < 256.
  Hypothesis SH : u8arr bsegs m (sh addr) sbs.  Hypothesis SHL : Z.of_nat (length sbs) = size / 8.
  Hypothesis CCAN : rw_cells bsegs m ACANPOISON [C1 (b8 1)].
  Hypothesis GOT : rw_cells bsegs m AGOT_LO (map (fun v => C8 (wz v)) AGOT_VALS).
  Hypothesis CSHB : rw_cells bsegs m ASHBASE_CELL [C8 (wz ASHADOW_BASE)].
  Hypothesis CHME : rw_cells bsegs m AHIGHMEMEND [C8 (wz (2^47 - 1)); C8 (wz 0); C8 (wz 0)].
  Hypothesis CTHR : rw_cells bsegs m (ACFLAGS + 120) [C8 (wz 0xffffffffffffffff)].
  Hypothesis CRMS : rw_cells bsegs m AREALMEMSET [C8 (wz AMEMSET)].

